25	func (w *prefixErrWriter) Write(p []byte) (int, error) {
26		k := w.prefix
27		if k > len(p) {
28			k = len(p)
29		}
30		if k > 0 {
31			w.got.Write(p[:k])
32		}
33		if k < len(p) {
34			return k, w.err
35		}
36		return k, nil
37	}
