// scriptedResultWriter is the in-memory result destination. It behaves
// normally (buffering every byte) until it is asked to write the one target
// result line, where it applies an injected fault:
//
//   - accept < 0 means accept the whole line (len(p) bytes);
//   - otherwise accept up to that many bytes of the line.
//
// It then returns fault (which may be nil) for that one Write call, and stays
// broken afterwards in case the engine ever called again (it must not). Every
// byte it accepts is kept verbatim in got so the example can show exactly what
// landed. It records how many Write calls reached it.
type scriptedResultWriter struct {
	targetKey string
	accept    int // < 0 = full length
	fault     error
	got       bytes.Buffer
	calls     int
	struck    bool
}

func (w *scriptedResultWriter) Write(p []byte) (int, error) {
	w.calls++
	if w.struck || !w.isTarget(p) {
		// Normal behavior, including every result before the target line.
		return w.got.Write(p)
	}
	w.struck = true
	k := w.accept
	if k < 0 || k > len(p) {
		k = len(p)
	}
	if k > 0 {
		w.got.Write(p[:k])
	}
	if k < len(p) {
		return k, w.fault // partial prefix: fault may be nil (short write)
	}
	return k, w.fault // full line accepted, but fault is still honored
}

