	fmt.Print("result content confirmed as COMPLETE result lines:\n")
	printLines(confirmed)
	fmt.Print("raw bytes left by the FAILED write (a fragment, NOT a valid result):\n")
	printFragment(leftover)
	fmt.Printf("result writer Write calls attempted: %d\n", out.calls)
	fmt.Printf("late-event notice stream (lateLog): %s\n", emptyMarker(late.String()))
	fmt.Printf("returned error: %v\n", errString(err))

	classifyOutputError(err)
	fmt.Println()
}

// splitConfirmed partitions the bytes the result writer accepted into complete
// newline-terminated lines and a possible trailing fragment. Only a line that
// ends in '\n' is confirmed: the failed write's prefix (which cannot end at
// the newline) is returned separately as leftover, so it is never counted as a
// valid window result.
func splitConfirmed(data []byte) (confirmed []string, leftover []byte) {
	for len(data) > 0 {
		i := bytes.IndexByte(data, '\n')
		if i < 0 {
			return confirmed, data
		}
		confirmed = append(confirmed, string(data[:i+1]))
		data = data[i+1:]
	}
	return confirmed, nil
}

